# Each case is a list of 1-D input lengths. The output has prod(lengths) rows,
# so the groups stay small. The groups target distinct implementation branches
# of the submitted operator:
#   K == 2                  general chunk kernel with KP == 2
#   K == 3                  general kernel, one padded column tile slot
#   K == 4, even s_last     the row-paired 8-wide store specialisation
#   K == 4, odd s_last      general kernel (the pair path needs even s_last)
#   K >= 5, K == 8          more mixed-radix digits; K == 8 has zero padding
#   large s_last            more than one program along the row grid axis
K2_CASES = [[4, 3], [1, 1], [2, 1]]
K3_CASES = [[3, 4, 2], [2, 2, 2]]
K4_PAIR_CASES = [[4, 4, 4, 4], [2, 2, 2, 8], [8, 4, 2, 16]]
K4_ODD_CASES = [[3, 3, 3, 3], [5, 2, 3, 7]]
KN_CASES = [[2, 3, 4, 5, 2], [2, 2, 2, 2, 2, 2], [2, 2, 2, 2, 2, 2, 2, 2]]
MULTI_PROGRAM_CASES = [[2048, 3], [3, 2048], [1024, 3, 3]]
if QUICK_MODE:
    K2_CASES = [[4, 3]]
    K3_CASES = [[3, 4, 2]]
    K4_PAIR_CASES = [[4, 4, 4, 4]]
    K4_ODD_CASES = [[3, 3, 3, 3]]
    KN_CASES = [[2, 3, 4, 5, 2]]
    MULTI_PROGRAM_CASES = [[2048, 3]]

# (lengths, per-input strides): strided slices exercise the kernel's in-stride
# branch. Strides must be >= 1 and the result must stay 1-D.
STRIDED_CASES = [([6, 5], [2, 1]), ([4, 4, 3], [1, 3, 1]), ([5, 5], [3, 3])]
if QUICK_MODE:
    STRIDED_CASES = [([6, 5], [2, 1])]

SWEEP_DTYPES = utils.FLOAT_DTYPES + utils.INT_DTYPES + utils.BOOL_TYPES

EMPTY_CASES = [[0, 3], [3, 0], [2, 0, 4], [0, 0], [0, 0, 0, 0]]
if QUICK_MODE:
    EMPTY_CASES = [[0, 3], [2, 0, 4]]

ORDER_CASE = [[3, 2, 4]]
if QUICK_MODE:
    ORDER_CASE = [[2, 3]]


def _make_1d(length, dtype, seed=0):
    """Build a 1-D tensor of ``length`` elements on the gems device.

    Generators are seeded so the same values are produced on the reference and
    device paths. cartesian_prod only permutes input elements, so the
    comparison against the reference is exact for every supported dtype.
    """
    gen = torch.Generator().manual_seed(seed * 1000 + length)
    if dtype in utils.BOOL_TYPES:
        return torch.randint(0, 2, (length,), generator=gen).to(
            dtype=torch.bool, device=flag_gems.device
        )
    if dtype in utils.INT_DTYPES:
        return torch.randint(-1000, 1000, (length,), generator=gen).to(
            dtype=dtype, device=flag_gems.device
        )
    return torch.randn(length, generator=gen).to(dtype=dtype, device=flag_gems.device)


def _make_case(lengths, dtype, strides=None):
    """Return (device_inputs, reference_inputs) for one test case.

    Reference tensors are derived from the *converted* base tensor, never
    converted separately: ``Tensor.to("cpu")`` materializes a contiguous copy,
    so converting a strided view would lose the stride and the reference would
    stop matching (the ``--ref=cpu`` trap). Slicing the converted base keeps
    the reference on the same storage with the same stride.
    """
    device_tensors, ref_tensors = [], []
    for i, length in enumerate(lengths):
        step = 1 if strides is None else strides[i]
        backing_len = length * step if step > 1 else length
        backing = _make_1d(backing_len, dtype, seed=i)
        ref_backing = utils.to_reference(backing)
        if step > 1 and length > 0:
            device_tensors.append(backing[::step][:length])
            ref_tensors.append(ref_backing[::step][:length])
        else:
            device_tensors.append(backing)
            ref_tensors.append(ref_backing)
    return device_tensors, ref_tensors


def _shape_fragment(t):
    """Render a shape in a build-agnostic way (A1).

    This build's native message renders IntArrayRef as ``[3, 3]``; other
    builds may print the tuple form ``(3, 3)``. Accept either rendering so a
    different runner torch cannot fail the assertion on wording alone.
    """
    dims = ", ".join(str(int(s)) for s in t.shape)
    return ("[" + dims + "]", "(" + dims + ")")


@pytest.mark.cartesian_prod
@pytest.mark.parametrize(
    "lengths",
    K2_CASES + K3_CASES + K4_PAIR_CASES + K4_ODD_CASES + KN_CASES,
)
@pytest.mark.parametrize("dtype", SWEEP_DTYPES)
def test_accuracy_cartesian_prod(lengths, dtype):
    k = len(lengths)
    inp, ref_inp = _make_case(lengths, dtype)
    ref_out = torch.ops.aten.cartesian_prod(ref_inp)

    res_out = flag_gems.cartesian_prod(inp)

    assert tuple(res_out.shape) == (math.prod(lengths), k) == tuple(ref_out.shape)
    assert res_out.dtype == ref_out.dtype == dtype
    assert res_out.device == inp[0].device
    # Freshly allocated output: it never aliases any input.
    for t in inp:
        assert res_out.data_ptr() != t.data_ptr()
    assert res_out._base is None
    assert res_out.is_contiguous() == ref_out.is_contiguous()
    # Row order must match native lexicographic order (last input fastest).
    assert res_out.tolist() == ref_out.tolist()
    utils.gems_assert_equal(res_out, ref_out)


@pytest.mark.cartesian_prod
@pytest.mark.parametrize("lengths,strides", STRIDED_CASES)
@pytest.mark.parametrize("dtype", [torch.float32, torch.int32, torch.bool])
def test_accuracy_cartesian_prod_strided_inputs(lengths, strides, dtype):
    # Non-contiguous 1-D inputs: the kernel reads through each input's logical
    # stride (data_ptr + stride), so no materializing copy is required. The
    # output is always contiguous, matching native.
    inp, ref_inp = _make_case(lengths, dtype, strides=strides)
    for t, step in zip(inp, strides):
        assert t.dim() == 1
        if step > 1 and t.numel() > 0:
            assert not t.is_contiguous()
    ref_out = torch.ops.aten.cartesian_prod(ref_inp)

    res_out = flag_gems.cartesian_prod(inp)

    assert tuple(res_out.shape) == tuple(ref_out.shape)
    assert res_out.is_contiguous()
    assert res_out.stride() == (len(lengths), 1)
    assert res_out.tolist() == ref_out.tolist()
    utils.gems_assert_equal(res_out, ref_out)


