@pytest.mark.cartesian_prod
@pytest.mark.parametrize("lengths", ORDER_CASE)
def test_accuracy_cartesian_prod_order_is_lexicographic(lengths):
    # Independent ordering check (itertools.product is the documented
    # semantics): the last input varies fastest and rows are lexicographic.
    inp, _ = _make_case(lengths, torch.int32)
    values = [t.tolist() for t in inp]
    want_rows = [
        [values[j][idx[j]] for j in range(len(lengths))]
        for idx in itertools.product(*(range(n) for n in lengths))
    ]

    res_out = flag_gems.cartesian_prod(inp)

    assert res_out.tolist() == want_rows
    # Cross-check against the ATen reference row by row.
    ref_out = torch.ops.aten.cartesian_prod([t.cpu() for t in inp])
    assert res_out.tolist() == ref_out.tolist()


