@pytest.mark.cartesian_prod
def test_accuracy_cartesian_prod_repeated_calls_are_stable():
    # Five repeated calls must return consistent values, and the outputs of
    # separate calls are independent allocations.
    lengths = [4, 3]
    inp, ref_inp = _make_case(lengths, torch.float32)
    ref_out = torch.ops.aten.cartesian_prod(ref_inp)

    outs = [flag_gems.cartesian_prod(inp) for _ in range(5)]

    for out in outs:
        utils.gems_assert_equal(out, ref_out)
    # Each call allocates its own output storage.
    for i in range(len(outs)):
        for j in range(i + 1, len(outs)):
            assert outs[i].data_ptr() != outs[j].data_ptr()


@pytest.mark.cartesian_prod
@pytest.mark.parametrize("lengths", K2_CASES + K4_ODD_CASES)
def test_accuracy_cartesian_prod_non_1d_raises(lengths):
    # Native rejects any input whose dim != 1 (0-dim and 2-D included) with
    # RuntimeError before any dtype or device check. Assert the exception
    # class plus semantic fragments (the offending shape) rather than one
    # build's full sentence: CI's runner torch is a different build (A1).
    inp, _ = _make_case(lengths, torch.float32)
    good = inp[0]
    bad_2d = _make_1d(lengths[0] * lengths[1], torch.float32).reshape(*lengths[:2])
    bad_0d = _make_1d(1, torch.float32)[0]

    for bad in (bad_2d, bad_0d):
        with pytest.raises(RuntimeError) as excinfo:
            flag_gems.cartesian_prod([good, bad])
        message = str(excinfo.value)
        assert "1D" in message
        assert any(fragment in message for fragment in _shape_fragment(bad))


