    cuda_t = _make_1d(3, torch.float32)
    cpu_t = torch.arange(2, dtype=torch.float32)

    with pytest.raises(RuntimeError) as excinfo:
        flag_gems.cartesian_prod([cuda_t, cpu_t])
    assert "device" in str(excinfo.value)


